def find_docstring(key, attribute):
    """Find the docstring for *attribute* of *key* in the bases.

    ``attribute`` is used to select the matching attribute on the
    base class (e.g. ``'fget'`` for the getter of a property).
    """
    for base in cls.__mro__[1:]:
        super_method = getattr(base, key, None)
        if super_method is None:
            continue
        if attribute is not None:
            super_method = getattr(super_method, attribute, None)
            if super_method is None:
                continue
        return super_method.__doc__
    return None

for key, val in dct.items():
